import{_ as s,o as n,c as a,a2 as t}from"./chunks/framework.CYj0tiXz.js";const m=JSON.parse('{"title":"Changelog","description":"BlendSDK release notes and version history","frontmatter":{"title":"Changelog","description":"BlendSDK release notes and version history"},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1790812580000}'),o={name:"reference/changelog.md"};function r(i,e,l,c,d,p){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="blendsdk-v5-65-0-—-release-notes" tabindex="-1">BlendSDK v5.65.0 — Release Notes <a class="header-anchor" href="#blendsdk-v5-65-0-—-release-notes" aria-label="Permalink to &quot;BlendSDK v5.65.0 — Release Notes&quot;">​</a></h1><p><strong>Released</strong>: 2026-09-27</p><p>We are excited to announce the release of BlendSDK version 5.65.0! This latest update brings a range of enhancements and improvements across various packages that will benefit our users, enhance security, and streamline development processes.</p><h3 id="summary-of-key-changes" tabindex="-1">Summary of Key Changes <a class="header-anchor" href="#summary-of-key-changes" aria-label="Permalink to &quot;Summary of Key Changes&quot;">​</a></h3><ol><li><p><strong>Enhanced Security Measures</strong>: Several updates across the SDK packages focus on improving security, particularly around user authorization and session management. This includes stricter checks and hardening measures to safeguard user sessions, which will help in maintaining the integrity of user authentication processes.</p></li><li><p><strong>Better Documentation</strong>: As part of our commitment to user support, we have improved our documentation to ensure that developers can easily navigate and understand the SDK’s features. This includes clear guidelines on interactive elements and enhanced explanations of processes.</p></li><li><p><strong>New Features and Improved Functionality</strong>: We’ve introduced new features, such as authorization hooks and route guard components. These additions will make it easier for developers to implement security checks and manage user access more efficiently.</p></li><li><p><strong>Integration and Compatibility</strong>: The SDK now offers better integration capabilities with various services, allowing users to connect seamlessly with different technology stacks. Additionally, enhancements to our client and tooling will minimize setup time for new projects.</p></li><li><p><strong>Performance Improvements</strong>: Consistent updates have led to performance optimizations across multiple packages, which means faster load times and more efficient use of system resources during operation.</p></li></ol><p>These changes not only improve the SDK&#39;s overall functionality but also provide a more reliable and secure framework for developers. We believe these updates will enhance the user experience, allowing for more robust applications and a smoother development process. Thank you for your continued support as we strive to provide the best tools for your development needs!</p><hr><p><em>Install: <code>npm install blendsdk/stdlib@v5</code></em><em>Full changelog: See individual package CHANGELOG.md files</em></p>',8)])])}const h=s(o,[["render",r]]);export{m as __pageData,h as default};
